import * as E from './engine.js';
import {surface}from'./world.js';
export const NETWORK_VERSION=1;
export function rosterFromSave(s){return s.army.filter(u=>u.hp>0).slice(0,32).map(u=>({type:u.type,level:u.level,hp:Math.min(u.hp,E.unitStats(u.type,u.level).hp)}));}
export function validateRoster(value){if(!Array.isArray(value)||!value.length||value.length>32)throw Error('Ejército no válido.');let population=0;return value.map(u=>{if(!Object.hasOwn(E.UNITS,u.type)||!Number.isInteger(u.level)||u.level<1||u.level>5||!Number.isFinite(u.hp)||u.hp<=0)throw Error('Tropa no válida.');const spec=E.unitStats(u.type,u.level);population+=spec.pop;if(population>200)throw Error('El ejército supera las 200 plazas del duelo.');return{type:u.type,level:u.level,hp:Math.min(spec.hp,u.hp)};});}
export function createDuel(host,guest,seed=341){host=validateRoster(host);guest=validateRoster(guest);const s=E.createIslandState(seed,'hard');s.time=0;s.army=[];s.workforce.workers=[];s.buildings=[];s.network={budgets:{host:{gold:1000,wood:1000,supply:1000,metal:1000},guest:{gold:1000,wood:1000,supply:1000,metal:1000}},result:null};const world={version:1,layout:'MAP_PLAYER_1',owned:[],bridges:[],revision:0,nature:'arena',mission:true,obstacles:[]},b=s.battle={kind:'network',name:'Duelo entre comandantes',seed,world,elapsed:0,limit:1200,buildings:[],units:[],reserve:[],effects:[],dead:[],serial:0};
 for(const[owner,roster,x,y,side]of[['host',host,41,36,'player'],['guest',guest,62,57,'enemy']]){for(const[type,dx,dy]of[['hq',0,0],['tower',owner==='host'?4:-2,0]]){const st=E.buildingStats(type,3);b.buildings.push({id:owner+'-'+type,type,owner,x:x+dx,y:y+dy,level:3,hp:st.hp,maxHp:st.hp,attack:st.attack,range:st.range,side});}roster.forEach((r,i)=>{const u=E.makeUnit(s,r.type,r.level);Object.assign(u,{id:owner+'-unit-'+i,owner,side,hp:r.hp,x:x+(i%4)*.8-1,y:y+(owner==='host'?5:-3)+Math.floor(i/4)*.8,loaned:true,cooldown:0,order:{kind:'hold',x,y}});if(E.UNITS[u.type].waterborne){let point=null,d=Infinity;for(let yy=1;yy<99;yy++)for(let xx=1;xx<99;xx++)if(surface(b,xx,yy)==='water'){const q=(xx-u.x)**2+(yy-u.y)**2;if(q<d){d=q;point={x:xx+.5,y:yy+.5};}}Object.assign(u,point);u.order={kind:'hold',x:u.x,y:u.y};}b.units.push(u);});}return s;
}
export function applyNetworkCommand(s,owner,c){if(!s.battle||s.network?.result||!['host','guest'].includes(owner)||!c||!Array.isArray(c.ids)||c.ids.length>96||!['move','attack','hold','ability'].includes(c.kind)||!Number.isFinite(c.x)||!Number.isFinite(c.y)||c.x<1||c.y<1||c.x>=99||c.y>=99)return{ok:false,message:'Orden no válida.'};const list=s.battle.units.filter(u=>u.owner===owner&&u.hp>0&&!u.embarked&&c.ids.includes(u.id));if(!list.length)return{ok:false,message:'No puedes dirigir las tropas del otro comandante.'};if(c.kind==='ability'){const resources=s.resources;s.resources=s.network.budgets[owner];const r=E.castAbility(s,list.map(u=>u.id),c.ability,c.x,c.y,owner==='host'?'player':'enemy');s.network.budgets[owner]=s.resources;s.resources=resources;return r;}list.forEach((u,i)=>u.order={kind:c.kind,x:Math.min(98.5,c.x+(i%4)*.45),y:Math.min(98.5,c.y+Math.floor(i/4)*.45)});return{ok:true,message:'Orden recibida.'};}
export function tickDuel(s,dt){if(s.network.result)return;s.time+=dt;E.tickBattle(s,dt);const b=s.battle,h=b.buildings.find(v=>v.id==='host-hq'),g=b.buildings.find(v=>v.id==='guest-hq');if(h.hp<=0||g.hp<=0||b.elapsed>=b.limit){let winner=h.hp<=0&&g.hp<=0?'draw':h.hp<=0?'guest':g.hp<=0?'host':h.hp/h.maxHp===g.hp/g.maxHp?'draw':h.hp/h.maxHp>g.hp/g.maxHp?'host':'guest';s.network.result={winner,elapsed:b.elapsed};}}
const encode=value=>btoa(JSON.stringify(value)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
export function parseInvitation(code,expectedKind){if(typeof code!=='string'||code.length>60000)throw Error('Código demasiado grande.');const data=JSON.parse(atob(code.trim().replace(/-/g,'+').replace(/_/g,'/')));if(data.version!==NETWORK_VERSION||data.kind!==expectedKind||typeof data.room!=='string'||!/^[a-f0-9]{32}$/.test(data.room)||data.description?.type!==expectedKind||typeof data.description.sdp!=='string'||data.description.sdp.length>40000)throw Error('Código de invitación no válido.');return data;}
const gather=pc=>new Promise(resolve=>{if(pc.iceGatheringState==='complete')return resolve();const timer=setTimeout(done,12000);function done(){clearTimeout(timer);pc.removeEventListener('icegatheringstatechange',changed);resolve();}function changed(){if(pc.iceGatheringState==='complete')done();}pc.addEventListener('icegatheringstatechange',changed);});
export class PeerRoom{
 constructor({roster,name='Comandante',iceServers=[{urls:'stun:stun.l.google.com:19302'}],onState=()=>{},onStatus=()=>{},onMessage=()=>{}}){this.roster=validateRoster(roster);this.name=String(name).slice(0,24);this.iceServers=iceServers;this.onState=onState;this.onStatus=onStatus;this.onMessage=onMessage;this.sequence=0;this.receivedSequence=0;this.lastSeen=0;this.closed=false;}
 setup(role){if(this.pc)this.close();this.closed=false;this.role=role;this.pc=new RTCPeerConnection({iceServers:this.iceServers});this.pc.onconnectionstatechange=()=>{if(this.closed)return;const state=this.pc.connectionState;this.onStatus(state==='connected'?'Conectado':state==='failed'?'No se pudo establecer la conexión. Prueba otra red o configura un servidor TURN.':state==='disconnected'?'Conexión interrumpida; el duelo se pausa.':'Conectando…');};this.pc.ondatachannel=e=>this.bind(e.channel);}
 bind(channel){this.channel=channel;channel.onopen=()=>{this.lastSeen=performance.now();this.onStatus('Conectado');this.send({type:'hello',version:NETWORK_VERSION,room:this.room,name:this.name,roster:this.roster});this.startClock();};channel.onmessage=event=>{try{if(typeof event.data!=='string'||event.data.length>180000)throw Error('Paquete no válido.');this.receive(JSON.parse(event.data));}catch{this.onMessage('Se rechazó un paquete no válido.');}};channel.onclose=()=>{if(!this.closed)this.onStatus('La otra persona se desconectó. El duelo está en pausa.');};}
 send(message){if(this.channel?.readyState!=='open'||this.channel.bufferedAmount>128000)return false;const raw=JSON.stringify(message);if(raw.length>170000)return false;this.channel.send(raw);return true;}
 async createOffer(){this.setup('host');this.room=Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');this.bind(this.pc.createDataChannel('auralis-duel',{ordered:true}));await this.pc.setLocalDescription(await this.pc.createOffer());await gather(this.pc);return encode({version:NETWORK_VERSION,kind:'offer',room:this.room,description:this.pc.localDescription.toJSON()});}
 async acceptOffer(code){const data=parseInvitation(code,'offer');this.setup('guest');this.room=data.room;await this.pc.setRemoteDescription(data.description);await this.pc.setLocalDescription(await this.pc.createAnswer());await gather(this.pc);return encode({version:NETWORK_VERSION,kind:'answer',room:this.room,description:this.pc.localDescription.toJSON()});}
 async acceptAnswer(code){const data=parseInvitation(code,'answer');if(this.role!=='host'||data.room!==this.room)throw Error('La respuesta pertenece a otra sala.');await this.pc.setRemoteDescription(data.description);}
 receive(data){if(data?.type==='hello'){if(data.version!==NETWORK_VERSION||data.room!==this.room)throw Error('Versión o sala incompatible.');this.remoteRoster=validateRoster(data.roster);this.remoteName=String(data.name||'Comandante').slice(0,24);this.lastSeen=performance.now();if(this.role==='host')this.restart();return;}if(data?.type==='ping'){this.lastSeen=performance.now();this.send({type:'pong'});return;}if(data?.type==='pong'){this.lastSeen=performance.now();return;}if(data?.type==='leave'){this.onStatus('La otra persona salió del duelo.');this.channel?.close();return;}
  if(this.role==='host'&&data?.type==='command'){if(!Number.isSafeInteger(data.sequence)||data.sequence<=this.receivedSequence||data.sequence>this.receivedSequence+1000)throw Error('Secuencia no válida.');const now=performance.now();if(now-(this.rateStart||0)>1000){this.rateStart=now;this.rateCount=0;}if((this.rateCount=(this.rateCount||0)+1)>30)return;this.receivedSequence=data.sequence;const result=applyNetworkCommand(this.state,'guest',data.command);if(!result.ok)this.send({type:'notice',message:result.message});return;}
  if(this.role==='guest'&&data?.type==='snapshot'){const s=data.state,b=s?.battle;if(!s||b?.kind!=='network'||!s.network||!Number.isFinite(s.time)||!Array.isArray(b.units)||b.units.length>100||!Array.isArray(b.buildings)||b.buildings.length!==4||b.world?.layout!=='MAP_PLAYER_1'||b.world?.nature!=='arena'||!Array.isArray(b.world.obstacles)||b.world.obstacles.length)throw Error('Estado de duelo no válido.');for(const u of b.units)if(!Object.hasOwn(E.UNITS,u.type)||!Number.isFinite(u.hp)||!Number.isFinite(u.x)||!Number.isFinite(u.y)||u.x<0||u.y<0||u.x>100||u.y>100||!['host','guest'].includes(u.owner))throw Error('Actor no válido.');for(const v of b.buildings)if(!['hq','tower'].includes(v.type)||!Number.isFinite(v.hp)||!Number.isFinite(v.x)||!Number.isFinite(v.y))throw Error('Base no válida.');this.state=s;this.lastSeen=performance.now();this.onState(s);return;}
  if(data?.type==='notice')this.onMessage(String(data.message||'Orden recibida.').slice(0,180));
 }
 restart(){if(this.role!=='host'||!this.remoteRoster)return;this.state=createDuel(this.roster,this.remoteRoster,crypto.getRandomValues(new Uint32Array(1))[0]);this.sequence=this.receivedSequence=0;this.onState(this.state);this.broadcast();}
 broadcast(){if(this.state)this.send({type:'snapshot',state:this.state});}
 command(command){if(this.role==='host'){const r=applyNetworkCommand(this.state,'host',command);if(!r.ok)this.onMessage(r.message);return r;}this.send({type:'command',sequence:++this.sequence,command});return{ok:true};}
 startClock(){clearInterval(this.timer);let last=performance.now(),sent=0,ping=0;this.timer=setInterval(()=>{if(this.channel?.readyState!=='open')return;const now=performance.now(),dt=Math.min(.25,(now-last)/1000);last=now;if(now-ping>2000){this.send({type:'ping'});ping=now;}if(this.role==='host'&&this.state&&now-this.lastSeen<10000){tickDuel(this.state,dt);this.onState(this.state);if(now-sent>150){this.broadcast();sent=now;}}},50);}
 close(){this.closed=true;clearInterval(this.timer);this.send({type:'leave'});this.channel?.close();this.pc?.close();this.pc=null;this.channel=null;}
}
